test('review: durable services consumer recovers existing V1 original receipt without new claim or generation', async () => {
  const f = await fixture(); f.rows.followup.dueConsumed = true; await f.seed();
  const originalReceipt = f.rows.run.resultEncrypted;
  await f.build().continuation!.process(f.job, f.job.jobId);
  assert.equal((await f.read('event')).state, 'completed');
  assert.equal((await f.read('run')).resultEncrypted, originalReceipt);
  assert.equal((await f.read('event')).inputEvidence, undefined);
  assert.deepEqual(f.stats(), { calls: 0, sql: 0 }); assert.equal(f.opens.length, 0);
